---- MONITORS ----
------------------

-- See https://wiki.hypr.land/configuring/core/monitors/
hl.monitor({
    output   = "",
    mode     = "preferred",
    position = "auto",
    scale    = "auto",
})


---------------------
---- MY PROGRAMS ----
---------------------

-- Set programs that you use
local terminal    = "kitty"
local fileManager = "env QT_QPA_PLATFORMTHEME=kde dolphin" -- Force KDE palette even before next Hyprland login
local menu = "@HOME@/.local/bin/hypr-app-launcher"


-------------------
---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/configuring/core/autostart/

-- Keep the existing auto-opened terminal and Firefox session.
-- Launch desktop components separately; hl.exec_cmd is already asynchronous.
hl.on("hyprland.start", function()
    hl.exec_cmd(terminal)
    hl.exec_cmd("firefox")
    hl.exec_cmd("nm-applet")
    hl.exec_cmd("waybar")
    hl.exec_cmd("hypridle")
    -- Presentation/Class Mode is session-scoped; restore normal after login.
    hl.exec_cmd("@HOME@/.local/bin/hypr-desktop-mode normal")
    -- KDE Connect tray and optional app-only layout restore after desktop startup.
    hl.exec_cmd("kdeconnect-indicator")
    hl.exec_cmd("sh -c 'sleep 6; @HOME@/.local/bin/hypr-session-layout auto apply'")
    -- Desktop Commander remote bridge in Kitty, assigned to workspace 9.
    hl.exec_cmd("@HOME@/.local/bin/hypr-desktop-commander")
    -- Two Wayland clipboard observers: text and images (local history).
    hl.exec_cmd("wl-paste --type text --watch cliphist store")
    hl.exec_cmd("wl-paste --type image --watch cliphist store")
    -- Starts automatically once the optional hyprsunset package is installed.
    hl.exec_cmd("@HOME@/.local/bin/hypr-night-light")
    -- Start wallpaper service only after choosing a wallpaper.
    hl.exec_cmd("sh -c 'test ! -s @HOME@/.config/hypr/hyprpaper.conf || exec hyprpaper'")
    -- Reversible Star Wars theme watcher. No changes when Catppuccin is selected.
    hl.exec_cmd("@HOME@/.local/bin/hypr-starwars watch")
end)


