---- KEYBINDINGS ----
---------------------

local mainMod = "SUPER" -- Sets "Windows" key as main modifier
hl.bind("SUPER + L", hl.dsp.exec_cmd("loginctl lock-session"))
-- Open a confirmation-based power/logout menu.
hl.bind("SUPER + SHIFT + E", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-power-menu"))
-- Capture a selected region directly to the clipboard (Ctrl+V to paste).
-- Super+Shift+S is already used for the special workspace, so use A instead.
-- Chromebook screenshot shortcuts: no Print Screen or function keys required.
hl.bind("SUPER + SHIFT + A", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-screenshot region-copy"))
hl.bind("SUPER + SHIFT + D", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-screenshot region-save"))
hl.bind("SUPER + SHIFT + F", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-screenshot full-copy"))
hl.bind("SUPER + SHIFT + G", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-screenshot full-save"))
-- Both Super+R and Super+Space use the same translucent Wofi launcher.
hl.bind("SUPER + SPACE", hl.dsp.exec_cmd(menu))
-- Show a live, searchable cheatsheet of every currently registered binding.
hl.bind("SUPER + comma", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-keybinds"))
-- Notification history and quiet mode for classes.
hl.bind("SUPER + N", hl.dsp.exec_cmd("makoctl restore"))
hl.bind("SUPER + SHIFT + N", hl.dsp.exec_cmd("makoctl mode -t do-not-disturb"))
-- Clipboard history preserves text and image MIME types for Ctrl+V.
hl.bind("SUPER + SHIFT + V", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-clipboard"))
-- Chromebook-specific utilities; no function keys needed.
hl.bind("SUPER + SHIFT + Q", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-quick-settings"))
-- Galactic appearance menu: Imperial / Sith / Rakatan / original Catppuccin.
hl.bind("SUPER + SHIFT + Y", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-starwars menu"))
-- HoloNet Command Console; retains Super+Space as direct application search.
hl.bind("SUPER + SHIFT + O", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-holonet-launcher"))
-- Alternate shortcut for the Sith Holocron Vault.
hl.bind("SUPER + SHIFT + J", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-sith-vault"))
hl.bind("SUPER + SHIFT + W", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-wallpaper-picker"))
hl.bind("SUPER + SHIFT + P", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-screenshot-edit region"))
hl.bind("SUPER + SHIFT + R", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-record start region"))
hl.bind("SUPER + SHIFT + T", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-record stop"))
-- Study / presentation modes and the notification + device centers.
hl.bind("SUPER + SHIFT + C", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-desktop-mode class"))
hl.bind("SUPER + SHIFT + M", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-desktop-mode presentation"))
hl.bind("SUPER + SHIFT + B", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-desktop-mode normal"))
hl.bind("SUPER + SHIFT + H", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-notifications"))
hl.bind("SUPER + SHIFT + K", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-devices"))
-- Example binds, see https://wiki.hypr.land/configuring/core/binds/ for more
-- Quick application launches (Search/Super key on Chromebook).
hl.bind(mainMod .. " + B", hl.dsp.exec_cmd("firefox"))  -- Browser
hl.bind(mainMod .. " + D", hl.dsp.exec_cmd("discord"))  -- Discord
hl.bind(mainMod .. " + I", hl.dsp.exec_cmd("code"))     -- VS Code / IDE
hl.bind(mainMod .. " + Q", hl.dsp.exec_cmd(terminal))
local closeWindowBind = hl.bind(mainMod .. " + C", hl.dsp.window.close())
-- closeWindowBind:set_enabled(false)
hl.bind(mainMod .. " + M", hl.dsp.exec_cmd("command -v hyprshutdown >/dev/null 2>&1 && hyprshutdown || hyprctl dispatch 'hl.dsp.exit()'"))
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + V", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + R", hl.dsp.exec_cmd(menu))
hl.bind(mainMod .. " + P", hl.dsp.window.pseudo())
hl.bind(mainMod .. " + J", hl.dsp.layout("togglesplit"))    -- dwindle only

-- Move focus with mainMod + arrow keys
hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "down" }))

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key,             hl.dsp.focus({ workspace = i}))
    hl.bind(mainMod .. " + SHIFT + " .. key,     hl.dsp.window.move({ workspace = i }))
end

-- Example special workspace (scratchpad)
hl.bind(mainMod .. " + S",         hl.dsp.workspace.toggle_special("magic"))
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.window.move({ workspace = "special:magic" }))

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Chromebook Kano (rev3) physical top row (Linux reports dedicated key events).
-- Back and Refresh send their usual browser shortcuts to the focused application.
hl.bind("XF86Back", function()
    hl.dispatch(hl.dsp.send_shortcut({ mods = "ALT", key = "Left" }))
end)
hl.bind("XF86Reload", function()
    hl.dispatch(hl.dsp.send_shortcut({ mods = "CTRL", key = "R" }))
end)

-- Full-screen and Overview keys on the ChromeOS top row.
hl.bind("XF86FullScreen", function()
    hl.dispatch(hl.dsp.window.fullscreen({ action = "toggle", mode = "fullscreen" }))
end)
hl.bind("XF86LaunchA", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-overview-grid"))
-- Chromebook screenshot key emits Print even though it is marked with a camera icon.
hl.bind("Print", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-screenshot region-copy"))
hl.bind("SHIFT + Print", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-screenshot region-save"))
hl.bind("CTRL + Print", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-screenshot full-copy"))
-- Open the fullscreen Sith Holocron Vault workspace picker.
hl.bind("SUPER + Tab", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-sith-vault"))

-- The physical lock/power key is handled by hardware/logind; leave it unchanged
-- to avoid accidentally shutting down or suspending this running laptop.
-- Laptop multimedia keys for volume and LCD brightness
-- Mako progress overlays appear when the Chromebook top-row keys are pressed.
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-controls volume-up"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-controls volume-down"), { locked = true, repeating = true })
hl.bind("XF86AudioMute", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-controls volume-mute"), { locked = true, repeating = true })
hl.bind("XF86AudioMicMute", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-controls mic-mute"), { locked = true, repeating = true })
hl.bind("XF86MonBrightnessUp", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-controls brightness-up"), { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-controls brightness-down"), { locked = true, repeating = true })

-- Requires playerctl
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd("playerctl next"),       { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("playerctl previous"),   { locked = true })


--------------------------------
---- WINDOWS AND WORKSPACES ----
--------------------------------

-- See https://wiki.hypr.land/configuring/core/rules/

-- Desktop Commander is kept on workspace 9 without stealing focus at login.
-- The custom Kitty class avoids moving ordinary terminal windows.
hl.window_rule({
    name = "desktop-commander-workspace-9",
    match = { class = "^chromebook-desktop-commander$" },
    workspace = "9 silent",
})

-- Open selected applications on dedicated workspaces.
-- Workspace rules take effect when a new application window is created.
-- Non-silent placement follows the newly launched app to its workspace.
hl.window_rule({
    name = "firefox-workspace-1",
    match = { class = "^firefox$" },
    workspace = "1",
})
-- Regular Kitty terminals go to workspace 2. Desktop Commander uses a
-- separate window class and retains its dedicated workspace 9.
hl.window_rule({
    name = "terminal-workspace-2",
    match = { class = "^(kitty)$" },
    workspace = "2",
})
-- Explicit Galactic terminal profiles complement ordinary Kitty's workspace rule.
for _, profile in ipairs({
    { class = "galactic-sith", target = "2" },
    { class = "galactic-rakatan", target = "3" },
    { class = "galactic-imperial", target = "1" },
}) do
    hl.window_rule({
        name = "galactic-" .. profile.target .. "-workspace",
        match = { class = "^" .. profile.class .. "$" },
        workspace = profile.target,
    })
end
hl.window_rule({
    name = "holonet-search-panel",
    match = { class = "^holonet-search$" },
    float = true, center = true,
})
hl.window_rule({
    name = "galactic-tactical-quick-settings",
    match = { class = "^hypr-quick-settings$" },
    float = true, center = true, size = "540 660",
})
hl.window_rule({
    name = "fleet-communications-log",
    match = { class = "^hypr-notifications$" },
    float = true, center = true,
})
hl.window_rule({
    name = "sith-holocron-vault-picker",
    match = { class = "^Sith Holocron Vault$" },
    float = true, center = true,
})
hl.window_rule({
    name = "vscode-workspace-3",
    match = { class = "^(code|Code|code-oss|com[.]microsoft[.]VSCode)$" },
    workspace = "3",
})
hl.window_rule({
    name = "discord-workspace-4",
    match = { class = "^(discord|Discord)$" },
    workspace = "4",
})
-- Keep utility windows floating, centered and comfortably sized.
hl.window_rule({
    name = "float-small-utilities",
    match = { class = "^(org[.]gnome[.]Calculator|gnome-calculator|qalculate-gtk|pavucontrol|nm-connection-editor)$" },
    float = true, center = true, size = "820 540",
})
-- Native file chooser titles when exported as separate windows.
hl.window_rule({
    name = "float-file-choosers",
    match = { title = "^(Open File|Save File|Select a File|Choose Files)$" },
    float = true, center = true,
})

-- Example window rules that are useful

local suppressMaximizeRule = hl.window_rule({
    -- Ignore maximize requests from all apps. You'll probably like this.
    name  = "suppress-maximize-events",
    match = { class = ".*" },

    suppress_event = "maximize",
})
-- suppressMaximizeRule:set_enabled(false)

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})

